import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const session: ChatSession = {
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content: 'hello', timestamp: new Date().toISOString()}],
};

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator onError wrapping', () => {
  it.each([['a string', 'boom'], ['a plain object', {code: 503}], ['undefined', undefined]])(
    'passes %s to onError as an Error whose cause is the original, and rethrows the original',
    async (_label, reason) => {
      const seen: Error[] = [];
      const orchestrator = createChatOrchestrator(
        rejectingWith(reason),
        new PromptBuilder({identity: 'You are a test assistant.'}),
        undefined,
        {hooks: {onError: async (_s, error) => void seen.push(error)}}
      );

      const thrown = await orchestrator.processMessage(session).then(
        () => 'resolved' as unknown,
        (e: unknown) => e
      );

      expect({thrown, count: seen.length, isError: seen[0] instanceof Error, cause: seen[0]?.cause}).toEqual({
        thrown: reason,
        count: 1,
        isError: true,
        cause: reason,
      });
    }
  );
});
EOF
